import { z } from "zod";

// Bexio's two record types are an API detail, not a customer type selector.
export const bexioContactTypeSchema = z.enum(["company", "person"]);
export type BexioContactType = z.infer<typeof bexioContactTypeSchema>;
export const bexioSyncStatusSchema = z.enum(["linked", "pending", "synced", "error"]);
export type BexioSyncStatus = z.infer<typeof bexioSyncStatusSchema>;

export function isRealCustomerEmail(email: string) {
  return z.email().safeParse(email).success && !email.toLowerCase().endsWith(".invalid");
}

export const forgeCustomerSchema = z.object({
  localCustomerId: z.string().trim().min(1).max(200),
  fullName: z.string().trim().min(1),
  email: z.email(),
  language: z.string().trim().min(2).max(16),
  companyName: z.string().nullable(),
  phone: z.string().nullable(),
  street: z.string().nullable().default(null),
  addressComplement: z.string().nullable().default(null),
  postalCode: z.string().nullable().default(null),
  city: z.string().nullable().default(null),
  countryCode: z.string().nullable().default(null),
});
export type ForgeCustomer = z.infer<typeof forgeCustomerSchema>;

export const bexioContactSchema = z.object({
  id: z.number().int().positive(),
  contact_type_id: z.union([z.literal(1), z.literal(2)]),
  name_1: z.string(),
  name_2: z.string().nullable().optional(),
  mail: z.string().nullable().optional(),
  phone_fixed: z.string().nullable().optional(),
  user_id: z.number().int().positive(),
  owner_id: z.number().int().positive(),
  updated_at: z.string().nullable().optional(),
});
export type BexioContact = z.infer<typeof bexioContactSchema>;

export const bexioRelationSchema = z.object({
  id: z.number().int().positive(),
  contact_id: z.number().int().positive(),
  contact_sub_id: z.number().int().positive(),
});
export type BexioRelation = z.infer<typeof bexioRelationSchema>;

export const bexioUserSchema = z.object({ id: z.number().int().positive(), email: z.email() });
export type BexioUser = z.infer<typeof bexioUserSchema>;

export const createBexioContactInputSchema = z.object({
  contactType: bexioContactTypeSchema,
  companyName: z.string().trim().min(1).nullable(),
  fullName: z.string().trim().min(1).nullable(),
  email: z.email().nullable(),
  language: z.string().trim().min(2).max(16),
  phone: z.string().trim().min(1).nullable(),
  street: z.string().trim().min(1).nullable(),
  addressComplement: z.string().trim().min(1).nullable(),
  postalCode: z.string().trim().min(1).nullable(),
  city: z.string().trim().min(1).nullable(),
  countryCode: z
    .string()
    .trim()
    .regex(/^[A-Z]{2}$/)
    .nullable(),
  ownerId: z.number().int().positive(),
});
export type CreateBexioContactInput = z.infer<typeof createBexioContactInputSchema>;
export const createAndLinkBexioContactInputSchema = z.object({
  localCustomerId: z.string().trim().min(1).max(200),
  contactType: bexioContactTypeSchema,
});
export type CreateAndLinkBexioContactInput = z.infer<typeof createAndLinkBexioContactInputSchema>;

export type BexioContactLink = {
  id: string;
  localCustomerId: string;
  bexioPersonId: number | null;
  bexioCompanyId: number | null;
  lastSyncedEmail: string | null;
  syncStatus: BexioSyncStatus;
  lastSyncedAt: Date | null;
  lastError: string | null;
  createdAt: Date;
  updatedAt: Date;
};
export type UpsertBexioContactLinkInput = Omit<BexioContactLink, "id" | "createdAt" | "updatedAt">;
export type UpdateBexioSyncStateInput = Pick<
  BexioContactLink,
  "syncStatus" | "lastSyncedAt" | "lastError"
> & {
  lastSyncedEmail?: string | null;
};
export type BexioSyncResult =
  | { status: "not-linked" }
  | { status: "synced"; link: BexioContactLink }
  | { status: "error"; link: BexioContactLink; message: string };

export const forgeCustomerImportInputSchema = z.object({
  fullName: z.string().trim().min(1),
  email: z.email().refine(isRealCustomerEmail, "A real contact email is required"),
  companyName: z.string().trim().min(1).nullable(),
  phone: z.string().trim().min(1).nullable(),
});
export type ForgeCustomerImportInput = z.infer<typeof forgeCustomerImportInputSchema>;
export const confirmBexioImportSchema = z.object({
  localCustomerId: z.string().trim().min(1).max(200),
  bexioPersonId: z.number().int().positive(),
  bexioCompanyId: z.number().int().positive().nullable(),
  expectedLocalEmail: z.email(),
  expectedRemoteEmail: z.email(),
  contact: forgeCustomerImportInputSchema,
});
export type ConfirmBexioImportInput = z.infer<typeof confirmBexioImportSchema>;
export type BexioImportPreview = ConfirmBexioImportInput;
export interface BexioCredentialProvider {
  getAccessToken(): Promise<string>;
}
export interface BexioContactClient {
  searchContacts(
    query: string,
    contactType: BexioContactType,
    exact?: boolean,
  ): Promise<BexioContact[]>;
  getContact(contactId: number): Promise<BexioContact>;
  ensureRelation(companyId: number, personId: number): Promise<void>;
  getAuthenticatedUser(): Promise<BexioUser>;
  createContact(input: CreateBexioContactInput): Promise<BexioContact>;
  updateContact(
    contactId: number,
    customer: ForgeCustomer,
    contactType: BexioContactType,
  ): Promise<BexioContact>;
}
export interface BexioContactLinkStore {
  getByLocalCustomerId(localCustomerId: string): Promise<BexioContactLink | null>;
  list(): Promise<BexioContactLink[]>;
  upsert(input: UpsertBexioContactLinkInput): Promise<BexioContactLink>;
  updateSyncState(
    localCustomerId: string,
    input: UpdateBexioSyncStateInput,
  ): Promise<BexioContactLink>;
  deleteByLocalCustomerId(localCustomerId: string): Promise<void>;
}
export interface ForgeCustomerAdapter {
  getCustomer(localCustomerId: string): Promise<ForgeCustomer>;
}
export interface ForgeCustomerImportAdapter {
  updateCustomer(
    localCustomerId: string,
    input: ForgeCustomerImportInput,
    expectedEmail: string,
  ): Promise<ForgeCustomer>;
}
export interface BexioContactLinkActions {
  getLink(localCustomerId: string): Promise<BexioContactLink | null>;
  searchContacts(query: string, contactType: BexioContactType): Promise<BexioContact[]>;
  linkContact(
    localCustomerId: string,
    bexioContactId: number,
    contactType: BexioContactType,
  ): Promise<BexioContactLink>;
  createContact(input: CreateAndLinkBexioContactInput): Promise<BexioContactLink>;
  unlinkContact(localCustomerId: string, contactType: BexioContactType): Promise<void>;
  syncContact(localCustomerId: string): Promise<BexioSyncResult>;
  previewImport(localCustomerId: string): Promise<BexioImportPreview>;
  confirmImport(input: ConfirmBexioImportInput): Promise<BexioContactLink>;
}

export type BexioPermission = "read" | "write";
export interface BexioHostAdapter {
  authorize(permission: BexioPermission, customerId?: string): Promise<boolean>;
  /** undefined locks the installation for bulk import, excluding every customer writer. */
  runExclusive<T>(customerId: string | undefined, operation: () => Promise<T>): Promise<T>;
}

export type ForgeCustomerEmailMatch =
  | { status: "not-found" }
  | { status: "customer"; customer: ForgeCustomer }
  | { status: "conflict"; message: string };
export interface ForgeCustomerBulkImportAdapter extends ForgeCustomerImportAdapter {
  findCustomersByEmails(emails: string[]): Promise<Map<string, ForgeCustomerEmailMatch>>;
  createCustomer(input: ForgeCustomerImportInput): Promise<ForgeCustomer>;
}
export interface BexioBulkContactClient extends BexioContactClient {
  listContacts(): Promise<BexioContact[]>;
  listRelations(): Promise<BexioRelation[]>;
}
export type BexioBulkSyncResult = {
  total: number;
  created: number;
  linked: number;
  updated: number;
  skipped: number;
  failed: number;
  issues: { bexioContactId: number; message: string }[];
};
export interface BexioCustomerDirectoryActions {
  listLinks(): Promise<BexioContactLink[]>;
  syncAllContacts(this: void): Promise<BexioBulkSyncResult>;
}

"use client";

import { QueryClient, useQuery } from "@tanstack/react-query";
import { RefreshCwIcon } from "lucide-react";
import { useState } from "react";

import { useActionToast } from "@/components/action-toast";
import type {
  BexioContactLinkActions,
  BexioContactType,
  BexioImportPreview,
} from "@/components/connectors/customers-bexio/contracts";
import { IconTooltip } from "@/components/icon-tooltip";
import { useLoadingActivity } from "@/components/loading-indicator";
import type { Customer } from "@/components/plugins/customers";
import {
  buttonClass,
  inputClass,
  outlineButtonClass,
  primaryButtonClass,
} from "@/components/plugins/customers/ui";
import { cn } from "@/components/utils/cn";
import { useMutationAction } from "@/components/utils/use-optimistic-action";

export type {
  BexioContact,
  BexioContactLink,
  BexioContactLinkActions,
  BexioContactType,
  BexioImportPreview,
  ForgeCustomer,
} from "@/components/connectors/customers-bexio/contracts";

export { BexioSyncAllButton, type BexioSyncAllButtonProps } from "./bulk-import";
export type { BexioBulkSyncResult, BexioCustomerDirectoryActions } from "./contracts";

export const customersBexioLabels = {
  title: "Bexio contacts",
  person: "Contact person",
  company: "Company (optional)",
  searchPerson: "Search people",
  searchCompany: "Search companies",
  search: "Search Bexio",
  empty: "No matching contacts.",
  searchHint: "Enter a name or email to find a contact.",
  link: "Link",
  unlink: "Unlink locally",
  create: "Create and link",
  confirmCreate: "Confirm creation",
  createDescription:
    "Create a Bexio contact from the saved customer details? Existing exact matches must be linked instead.",
  cancel: "Cancel",
  push: "Send to Bexio",
  pull: "Review import",
  confirmImport: "Confirm import",
  importDescription:
    "These values will replace the customer's contact details. An email change may affect account access.",
  name: "Name",
  email: "Email",
  phone: "Phone",
  companyName: "Company",
  emptyValue: "None",
  linked: "Linked",
  unlinked: "Not linked",
  synced: "Synchronized",
  pending: "Synchronizing",
  error: "Needs attention",
  loading: "Loading contacts…",
  refresh: "Reload contacts",
  readError: "Could not load contacts. Retry using Reload contacts.",
  actionError: "The action failed. Review the contact details and retry.",
  saved: "Contact connection updated.",
  readOnly: "You have read-only access to this connection.",
  contactId: "Bexio ID",
};
export type CustomersBexioLabels = typeof customersBexioLabels;
export interface BexioContactLinkCardProps {
  customerId: Customer["id"];
  actions: BexioContactLinkActions;
  search: Record<BexioContactType, string>;
  onSearchChange: (type: BexioContactType, query: string) => void;
  onImported?: () => void;
  onChanged?: () => void;
  canWrite?: boolean;
  labels?: Partial<CustomersBexioLabels>;
  className?: string;
}

export function BexioContactLinkCard(props: BexioContactLinkCardProps) {
  const [owner, setOwner] = useState({ actions: props.actions, version: 0 });
  if (owner.actions !== props.actions)
    setOwner({ actions: props.actions, version: owner.version + 1 });
  return <ContactLinkCard key={`${props.customerId}:${owner.version}`} {...props} />;
}
function ContactLinkCard({
  customerId,
  actions,
  search,
  onSearchChange,
  onImported,
  onChanged,
  canWrite = true,
  labels: overrides,
  className,
}: BexioContactLinkCardProps) {
  const labels = { ...customersBexioLabels, ...overrides };
  const [cache] = useState(() => new QueryClient());
  const link = useQuery(
    { queryKey: [customerId], queryFn: () => actions.getLink(customerId), retry: false },
    cache,
  );
  const mutation = useMutationAction(actions);
  const [confirmation, setConfirmation] = useState<{
    owner: typeof actions;
    value: BexioImportPreview | BexioContactType;
  } | null>(null);
  const confirm = confirmation?.owner === actions ? confirmation.value : null;
  const notify = useActionToast();
  useLoadingActivity(link.isFetching);
  const busy = mutation.pending || link.isFetching;
  const disabled = busy || !canWrite || link.isError || link.data === undefined;
  const status = link.data?.syncStatus;
  const statusLabel = status ? labels[status] : labels.unlinked;
  const statusClass =
    status === "synced"
      ? "bg-status-success text-status-success-foreground"
      : status === "error"
        ? "bg-status-canceled text-status-canceled-foreground"
        : status === "pending"
          ? "bg-status-pending text-status-pending-foreground"
          : "bg-status-not-started text-status-not-started-foreground";

  function change(operation: () => Promise<unknown>, imported = false) {
    if (disabled) return;
    void mutation.run(
      async () => {
        const result = await operation();
        const updated = await actions.getLink(customerId);
        return { result, updated };
      },
      ({ updated }) => {
        cache.setQueryData([customerId], updated);
        setConfirmation(null);
        if (!updated?.lastError) notify(labels.saved);
        onChanged?.();
        if (imported) onImported?.();
      },
    );
  }
  return (
    <section className={cn("space-y-6", className)} aria-label={labels.title} aria-busy={busy}>
      <header className="flex flex-wrap items-center justify-between gap-3">
        <h2 className="text-lg font-semibold">{labels.title}</h2>
        <div className="flex items-center gap-2">
          <span className={cn("rounded-md px-2 py-1 text-xs font-medium", statusClass)}>
            {statusLabel}
          </span>
          <IconTooltip label={labels.refresh}>
            <button
              type="button"
              className={buttonClass}
              aria-label={labels.refresh}
              disabled={busy}
              onClick={() => {
                setConfirmation(null);
                void cache.refetchQueries();
              }}
            >
              <RefreshCwIcon className="size-4" aria-hidden="true" />
            </button>
          </IconTooltip>
        </div>
      </header>
      {link.isPending && <output className="sr-only">{labels.loading}</output>}
      {link.isError && (
        <p role="alert" className="text-sm text-destructive">
          {labels.readError}
        </p>
      )}
      {!canWrite && <p className="text-sm text-muted-foreground">{labels.readOnly}</p>}
      <div className="grid gap-6 lg:grid-cols-2">
        {(["person", "company"] as const).map((type) => (
          <ContactSection
            key={type}
            type={type}
            customerId={customerId}
            contactId={type === "person" ? link.data?.bexioPersonId : link.data?.bexioCompanyId}
            search={search[type]}
            onSearchChange={(value) => onSearchChange(type, value)}
            actions={actions}
            cache={cache}
            labels={labels}
            disabled={disabled}
            readReady={link.data !== undefined && !link.isError}
            onLink={(id) => change(() => actions.linkContact(customerId, id, type))}
            onUnlink={() => change(() => actions.unlinkContact(customerId, type))}
            onCreate={() => setConfirmation({ owner: actions, value: type })}
          />
        ))}
      </div>
      <div className="flex flex-wrap gap-2">
        <button
          type="button"
          className={primaryButtonClass}
          disabled={disabled || !link.data}
          onClick={() => change(() => actions.syncContact(customerId))}
        >
          {labels.push}
        </button>
        <button
          type="button"
          className={outlineButtonClass}
          disabled={disabled || !link.data?.bexioPersonId}
          onClick={() => {
            void mutation.run(
              () => actions.previewImport(customerId),
              (value) => setConfirmation({ owner: actions, value }),
            );
          }}
        >
          {labels.pull}
        </button>
      </div>
      {confirm && (
        <section
          className="space-y-4 rounded-xl border border-border p-4"
          aria-label={typeof confirm === "string" ? labels.confirmCreate : labels.confirmImport}
        >
          <p className="text-sm">
            {typeof confirm === "string" ? labels.createDescription : labels.importDescription}
          </p>
          {typeof confirm !== "string" && (
            <dl className="grid gap-3 text-sm sm:grid-cols-2">
              {(
                [
                  [labels.name, confirm.contact.fullName],
                  [labels.email, confirm.contact.email],
                  [labels.phone, confirm.contact.phone],
                  [labels.companyName, confirm.contact.companyName],
                ] as const
              ).map(([title, value]) => (
                <div key={title}>
                  <dt className="text-muted-foreground">{title}</dt>
                  <dd className="break-words">{value || labels.emptyValue}</dd>
                </div>
              ))}
            </dl>
          )}
          <div className="flex flex-wrap gap-2">
            <button
              type="button"
              className={primaryButtonClass}
              disabled={disabled}
              onClick={() =>
                typeof confirm === "string"
                  ? change(() =>
                      actions.createContact({ localCustomerId: customerId, contactType: confirm }),
                    )
                  : change(() => actions.confirmImport(confirm), true)
              }
            >
              {typeof confirm === "string" ? labels.confirmCreate : labels.confirmImport}
            </button>
            <button
              type="button"
              className={buttonClass}
              disabled={busy}
              onClick={() => setConfirmation(null)}
            >
              {labels.cancel}
            </button>
          </div>
        </section>
      )}
      {link.data?.lastError && (
        <p role="alert" className="text-sm text-destructive">
          {link.data.lastError}
        </p>
      )}
      {mutation.error && (
        <p role="alert" className="text-sm text-destructive">
          {labels.actionError}
        </p>
      )}
    </section>
  );
}
function ContactSection({
  type,
  customerId,
  contactId,
  search,
  onSearchChange,
  actions,
  cache,
  labels,
  disabled,
  readReady,
  onLink,
  onUnlink,
  onCreate,
}: {
  type: BexioContactType;
  customerId: string;
  contactId?: number | null;
  search: string;
  onSearchChange: (value: string) => void;
  actions: BexioContactLinkActions;
  cache: QueryClient;
  labels: CustomersBexioLabels;
  disabled: boolean;
  readReady: boolean;
  onLink: (id: number) => void;
  onUnlink: () => void;
  onCreate: () => void;
}) {
  const [draft, setDraft] = useState({ source: search, value: search });
  if (draft.source !== search) setDraft({ source: search, value: search });
  const results = useQuery(
    {
      queryKey: [customerId, type, search],
      queryFn: () => actions.searchContacts(search, type),
      enabled: readReady && !contactId && Boolean(search.trim()),
      retry: false,
    },
    cache,
  );
  useLoadingActivity(results.isFetching);
  return (
    <section className="min-w-0 space-y-3" aria-label={labels[type]}>
      <h3 className="font-medium">{labels[type]}</h3>
      {contactId ? (
        <div className="flex flex-wrap items-center justify-between gap-2">
          <p className="text-sm">
            {labels.contactId}: <span className="font-mono">{contactId}</span>
          </p>
          <button
            type="button"
            className={outlineButtonClass}
            disabled={disabled}
            onClick={onUnlink}
          >
            {labels.unlink}
          </button>
        </div>
      ) : (
        <>
          <form
            className="flex flex-wrap gap-2"
            onSubmit={(event) => {
              event.preventDefault();
              if (draft.value.trim() === search) void results.refetch();
              else onSearchChange(draft.value.trim());
            }}
          >
            <input
              aria-label={type === "person" ? labels.searchPerson : labels.searchCompany}
              className={cn(inputClass, "min-w-0 flex-1 basis-40")}
              value={draft.value}
              maxLength={200}
              onChange={(event) => setDraft({ source: search, value: event.target.value })}
            />
            <button
              type="submit"
              className={outlineButtonClass}
              disabled={!readReady || results.isFetching || !draft.value.trim()}
            >
              {labels.search}
            </button>
          </form>
          <div className="min-h-12" aria-busy={results.isFetching}>
            {results.isError ? (
              <p role="alert" className="text-sm text-destructive">
                {labels.readError}
              </p>
            ) : results.isFetching ? (
              <output className="text-sm text-muted-foreground">{labels.loading}</output>
            ) : results.data?.length ? (
              <ul className="divide-y divide-border">
                {results.data.map((contact) => (
                  <li key={contact.id} className="flex items-center justify-between gap-3 py-2">
                    <div className="min-w-0 text-sm">
                      <p className="break-words">
                        {[contact.name_2, contact.name_1].filter(Boolean).join(" ")}
                      </p>
                      <p className="break-words text-muted-foreground">{contact.mail}</p>
                    </div>
                    <button
                      type="button"
                      className={outlineButtonClass}
                      disabled={disabled}
                      onClick={() => onLink(contact.id)}
                    >
                      {labels.link}
                    </button>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-sm text-muted-foreground">
                {search ? labels.empty : labels.searchHint}
              </p>
            )}
          </div>
          <button
            type="button"
            className={outlineButtonClass}
            disabled={disabled}
            onClick={onCreate}
          >
            {labels.create}
          </button>
        </>
      )}
    </section>
  );
}

"use client";

import { RefreshCwIcon } from "lucide-react";
import { useState } from "react";

import { useLoadingActivity } from "@/components/loading-indicator";
import { outlineButtonClass } from "@/components/plugins/customers/ui";
import { useMutationAction } from "@/components/utils/use-optimistic-action";

import type { BexioBulkSyncResult } from "./contracts";

const defaultLabels = {
  action: "Sync all from Bexio",
  pending: "Importing…",
  description:
    "Import Bexio contacts into customers. Existing login email changes require individual review.",
  error: "Import failed. Completed records remain saved. Resolve the connection issue and retry.",
  result: "Import results",
  created: "Created",
  linked: "Linked",
  updated: "Updated",
  skipped: "Skipped",
  failed: "Failed",
  issues: "Records needing review",
};
export interface BexioSyncAllButtonProps {
  syncAll: () => Promise<BexioBulkSyncResult>;
  onSynced?: (result: BexioBulkSyncResult) => void;
  canWrite?: boolean;
  labels?: Partial<typeof defaultLabels>;
}

export function BexioSyncAllButton({
  syncAll,
  onSynced,
  canWrite = true,
  labels: overrides,
}: BexioSyncAllButtonProps) {
  const labels = { ...defaultLabels, ...overrides };
  const mutation = useMutationAction(syncAll);
  const [completed, setCompleted] = useState<{
    owner: typeof syncAll;
    result: BexioBulkSyncResult;
  } | null>(null);
  if (completed && completed.owner !== syncAll) setCompleted(null);
  const result = completed?.owner === syncAll ? completed.result : null;
  useLoadingActivity(mutation.pending);
  return (
    <section className="space-y-3" aria-label={labels.action} aria-busy={mutation.pending}>
      <p className="text-sm text-muted-foreground">{labels.description}</p>
      <button
        type="button"
        className={outlineButtonClass}
        disabled={!canWrite || mutation.pending}
        onClick={() => {
          if (!canWrite) return;
          void mutation.run(syncAll, (value) => {
            setCompleted({ owner: syncAll, result: value });
            onSynced?.(value);
          });
        }}
      >
        <RefreshCwIcon className="size-4" aria-hidden="true" />
        {labels.action}
      </button>
      <div className="min-h-6 text-sm" aria-live="polite">
        {mutation.pending ? (
          labels.pending
        ) : mutation.error ? (
          <p role="alert" className="text-destructive">
            {labels.error}
          </p>
        ) : null}
      </div>
      {result && (
        <section className="space-y-3" aria-label={labels.result}>
          <dl className="flex flex-wrap gap-x-6 gap-y-2 text-sm">
            {(["created", "linked", "updated", "skipped", "failed"] as const).map((key) => (
              <div key={key}>
                <dt className="text-muted-foreground">{labels[key]}</dt>
                <dd className="font-medium">{result[key]}</dd>
              </div>
            ))}
          </dl>
          {result.issues.length > 0 && (
            <details>
              <summary className="cursor-pointer text-sm">{labels.issues}</summary>
              <ul className="mt-2 space-y-2 text-sm">
                {result.issues.map((issue, index) => (
                  <li key={`${issue.bexioContactId}-${index}`}>
                    #{issue.bexioContactId}: {issue.message}
                  </li>
                ))}
              </ul>
            </details>
          )}
        </section>
      )}
    </section>
  );
}
